// Banco de preguntas del tema E54. Formato y reglas: cabecera de src/data/preguntas.js.
export default [
  // ---------- TEMA 54 ESPECÍFICO · CATÁLOGO DEL PLAN MUNICIPAL (E54) ----------
  // Rehechas in situ el 18-10-2026 con la mezcla de tipos de los exámenes reales (GUIA_PREGUNTAS.md, 2 bis),
  // conservando los ids. Fuente única: temas/E_Tema54.txt con las correcciones de src/data/textosTemas/E54.js
  // (Normativa literal; arts. 32 y 36 en la redacción de la modificación aprobada por el Pleno el 03-07-2025,
  // BON n.º 155, de 05-08-2025, vigente a la convocatoria, BON 21-05-2026). 25-10-2026: retirada E54-08
  // (el art. 35 literal admite el traslado excepcional justificado y el cambio de emplazamiento en fachada);
  // la sustituye E54-16. 02-11-2026 (chequeo del tema): las tres META tenían la meta como correcta y la E54-03
  // pasa a tenerla falsa (correcta la a); E54-01 b) recoge literal el art. 39.7; E54-12 se ciñe al patrimonio
  // edificado (las alineaciones arboladas no son «elementos» de su art. 32); las DATO E54-04, 05 y 06 llevan las
  // cifras en escalera creciente sin cambiar de letra, y todas las exp citan el texto literal. Sin material
  // suprimido ni posterior al 21-05-2026. No se preguntan la estadística de la Memoria,
  // el marco legal derogado (LF 10/1994, DF 85/1995) ni la fecha límite de selección (Memoria, fuera del alcance).
  { id: "E54-01", tema: "E54", subtema: "Elementos no vinculados", tipo: "NEG",
    q: "Señale la respuesta INCORRECTA en relación con lo dispuesto en el artículo 39 de la Normativa General del Catálogo del Plan Municipal de Pamplona (Texto Refundido aprobado por Acuerdo de la Comisión de Ordenación del Territorio de 18 de diciembre de 2002) sobre las normas de protección de los elementos no vinculados a la edificación:",
    o: ["Las actuaciones permitidas son la conservación, la restauración y la consolidación.",
        "Se prohíbe la fijación permanente de publicidad en el monumento o en su entorno inmediato.",
        "Se autoriza la reestructuración del elemento cuando exista documentación suficiente.",
        "No se modifica el emplazamiento original, salvo justificación excepcional."],
    c: 2, exp: "Catálogo del Plan Municipal, Normativa General, art. 39 (normas de protección de los elementos no vinculados a la edificación): 39.1, «Las actuaciones permitidas en los elementos no vinculados catalogados serán las de conservación, restauración y consolidación»; 39.2, «No se autorizarán actuaciones de reestructuración ni demolición. Cuando exista documentación original: bocetos, reproducciones o imágenes que permitan conocer la disposición de partes perdidas o alteradas, se permitirá su restitución»; 39.3, si el emplazamiento es el original (o forma parte de la historia de la ciudad) «no se permitirá en general su modificación. No obstante, podrá autorizarse excepcionalmente cambiar el emplazamiento si se considera justificado»; 39.7, «Se prohíbe la fijación permanente de cualquier tipo de publicidad fijada al monumento o situada en su entorno inmediato». La c) es la INCORRECTA: cambia la RESTITUCIÓN por la REESTRUCTURACIÓN, que el artículo excluye expresamente. La a), la b) y la d) reproducen el art. 39." },
  { id: "E54-02", tema: "E54", subtema: "Patrimonio natural: régimen general", tipo: "NEG",
    q: "Conforme a lo establecido en el artículo 7 de la Normativa del patrimonio natural del Catálogo del Plan Municipal de Pamplona (Texto Refundido aprobado por Acuerdo de la Comisión de Ordenación del Territorio de 18 de diciembre de 2002), no es una de las reglas del régimen general de protección:",
    o: ["Se prohíbe toda actuación sobre el arbolado público sin autorización.",
        "Las podas importantes del arbolado se permiten como labores de mantenimiento.",
        "Las nuevas pavimentaciones se autorizan excepcionalmente y con informe técnico favorable.",
        "Se permiten labores de mantenimiento como el control fitosanitario o la cirugía de partes secas."],
    c: 1, exp: "Catálogo del Plan Municipal, Normativa del patrimonio natural, artículo 7: «Queda prohibida toda actuación sobre el arbolado público a las personas o entidades que no cuenten con la debida autorización»; las actuaciones que impliquen nuevas pavimentaciones o alteraciones del suelo, o eliminar ejemplares o «modificar sustancialmente las condiciones del arbolado (podas importantes, actuaciones en el terreno de proyección de las copas, nuevas plantaciones, etc...), sólo podrán autorizarse excepcionalmente por causa justificada y contando con un informe técnico favorable de los servicios municipales competentes»; y «Se permitirán las labores de mantenimiento y conservación del patrimonio arbóreo o vegetal» (control fitosanitario, cirugía de las partes secas y aumento de las superficies de aireación). La b) no es una de esas reglas: las podas importantes son una modificación sustancial del arbolado, autorizable solo de forma excepcional, y no una labor de mantenimiento permitida. Las otras tres reproducen el artículo." },
  { id: "E54-03", tema: "E54", subtema: "Edificios: régimen de obras por grado", tipo: "META",
    q: "Conforme a lo establecido en los artículos 26, 28 y 30 de la Normativa General del Catálogo del Plan Municipal de Pamplona (Texto Refundido aprobado por Acuerdo de la Comisión de Ordenación del Territorio de 18 de diciembre de 2002), son normas de actuación en los edificios catalogados:",
    o: ["En el grado 2 se autoriza la reestructuración parcial y se prohíbe la total.",
        "En el grado 3 se prohíben tanto la reestructuración total como el vaciado.",
        "En el grado 1 podrá autorizarse, con carácter excepcional, el vaciado.",
        "Las respuestas a) y c) son correctas."],
    c: 0, exp: "Catálogo del Plan Municipal, Normativa General, art. 28.3 (grado 2): «Podrán autorizarse las obras de reestructuración parcial. Se prohíbe la reestructuración total»; la a) es la correcta. La c) es falsa: para el grado 1, el art. 26.3 dice «Se prohíbe el vaciado del edificio», sin excepción; lo que en ese grado cabe «con carácter excepcional» es la reestructuración parcial para adaptarse a la normativa de incendios, evacuación o aparatos elevadores (art. 26.2), y también es excepcional la ampliación en planta (art. 26.14). La b) es falsa: según el art. 30.3, en el grado 3 «Son autorizables las obras de reestructuración total. Podrá autorizarse el vaciado del edificio». Como la c) es falsa, también lo es la d)." },
  { id: "E54-04", tema: "E54", subtema: "Glosario de obras", tipo: "DATO",
    q: "Según el glosario del artículo 8 de la Normativa General del Catálogo del Plan Municipal de Pamplona (Texto Refundido aprobado por Acuerdo de la Comisión de Ordenación del Territorio de 18 de diciembre de 2002), ¿a partir de qué parte de la superficie interior derribada, manteniendo las fachadas, se considera que la obra es un vaciado?",
    o: ["Más del 25 %.",
        "Más del 40 %.",
        "Más del 50 %.",
        "Más del 75 %."],
    c: 2, exp: "Catálogo del Plan Municipal, Normativa General, art. 8 (glosario): vaciado es el «Derribo de las estructuras internas horizontales y en su caso verticales de un edificio manteniendo las fachadas. Se considera vaciado, a los efectos de esta normativa, cuando el derribo supera el 50% de la superficie interior». Ni el 25 %, ni el 40 %, ni el 75 % figuran en la definición. El vaciado está prohibido en los grados 1 y 2 (arts. 26.3 y 28.4) y es autorizable en el grado 3 (art. 30.3)." },
  { id: "E54-05", tema: "E54", subtema: "Patrimonio natural: árboles aislados", tipo: "DATO",
    q: "De acuerdo con el Catálogo del Plan Municipal de Pamplona, en su Normativa del patrimonio natural, ¿hasta qué profundidad llega la parte subterránea protegida de un árbol aislado, delimitada por la proyección ortogonal de la copa?",
    o: ["1,5 m.",
        "2 m.",
        "2,5 m.",
        "3 m."],
    c: 0, exp: "Catálogo del Plan Municipal, Normativa del patrimonio natural, artículo 5.1 (árboles aislados): «Se incluye toda la parte aérea (tronco y copa), la parte subterránea (delimitada por la proyección ortogonal de la copa sobre el suelo, con una profundidad de 1,5 m.), así como la superficie de suelo que contiene dicha proyección». Las profundidades de 2 m, 2,5 m y 3 m no aparecen en la norma." },
  { id: "E54-06", tema: "E54", subtema: "Procedimiento: zonas arqueológicas", tipo: "DATO",
    q: "De conformidad con el artículo 42 de la Normativa General del Catálogo del Plan Municipal de Pamplona (Texto Refundido aprobado por Acuerdo de la Comisión de Ordenación del Territorio de 18 de diciembre de 2002), en las zonas arqueológicas situadas en ámbitos de Bien de Interés Cultural, ¿en qué plazo emite su informe preceptivo la Dirección General de Cultura-Institución Príncipe de Viana?",
    o: ["Diez días.",
        "Quince días.",
        "Un mes.",
        "Dos meses."],
    c: 3, exp: "Catálogo del Plan Municipal, Normativa General, art. 42.9: en los ámbitos delimitados como BIC, y mientras no se cree un Servicio Municipal de Arqueología, el Ayuntamiento presenta la documentación de la intervención ante la Dirección General de Cultura-Institución Príncipe de Viana, que «emitirá un informe, con carácter preceptivo, sobre la conveniencia de las medidas a desarrollar. Dicho informe deberá ser emitido en el plazo de dos meses, computados a partir de su fecha de entrada en el registro del Gobierno de Navarra». Diez días, quince días y un mes no son el plazo del artículo. En el mismo art. 42, en el Área A puede exigirse excavación o catas antes de la licencia que afecte al subsuelo (en ámbitos BIC se exige) y en el Área B, catas (en BIC, catas y seguimiento arqueológico intensivo)." },
  { id: "E54-07", tema: "E54", subtema: "Edificios: grados de protección", tipo: "META",
    q: "Según la Normativa General del Catálogo del Plan Municipal de Pamplona (Texto Refundido aprobado por Acuerdo de la Comisión de Ordenación del Territorio de 18 de diciembre de 2002), los edificios catalogados con grado 1 de protección:",
    o: ["Son los edificios más emblemáticos de la ciudad.",
        "Reciben una protección global para mantener sus características arquitectónicas, constructivas, volúmenes, formas y elementos decorativos.",
        "Constituyen un hito en la trama urbana.",
        "Todas las respuestas anteriores son correctas."],
    c: 3, exp: "Catálogo del Plan Municipal, Normativa General, art. 20.1: «Están incluidos en esta categoría los edificios más emblemáticos de la ciudad. Se protegen de forma global para mantener sus características arquitectónicas, constructivas, volúmenes, formas y elementos decorativos. Los edificios incluidos en este grado pueden ser considerados, en todo o en parte, elementos relevantes de la historia de la ciudad y constituyen un hito en la trama urbana». Las tres afirmaciones son literales, así que la correcta es la d). Recuérdese que los grados 1 y 2 protegen el edificio en su conjunto y el 3, en su mayoría, solo la fachada (art. 20)." },
  { id: "E54-08", tema: "E54", estado: "retirada", subtema: "Elementos vinculados a la edificación", tipo: "META",
    q: "Conforme a la Normativa General del Catálogo del Plan Municipal de Pamplona (Texto Refundido aprobado por Acuerdo de la Comisión de Ordenación del Territorio de 18 de diciembre de 2002), ¿cuándo puede modificarse el emplazamiento de un elemento vinculado a la edificación, como un escudo de armas?",
    o: ["Para devolverlo a su emplazamiento original.",
        "Cuando lo exija la rehabilitación de la fachada del edificio.",
        "Cuando el edificio que lo contiene no esté catalogado.",
        "Las respuestas a) y b) son correctas."],
    c: 0, exp: "Catálogo del Plan Municipal, Normativa General, art. 35 (elementos vinculados a la edificación): no se modifica el emplazamiento salvo para volver al ORIGINAL; la restauración se hace con técnicas específicas y la rehabilitación de la fachada se SUPEDITA a poner en valor el elemento, de modo que no puede justificar su traslado; por eso la b), y con ella la d), es falsa. La c) tampoco vale: según el art. 34 la catalogación de un elemento no supone catalogar la edificación, pero eso no altera el régimen del elemento, que se protege igualmente." },
  { id: "E54-09", tema: "E54", subtema: "Disposiciones generales: elementos de interés", tipo: "ALCANCE",
    q: "Conforme a lo establecido en el artículo 4 de la Normativa General del Catálogo del Plan Municipal de Pamplona (Texto Refundido aprobado por Acuerdo de la Comisión de Ordenación del Territorio de 18 de diciembre de 2002), la descripción de las fichas no es definitiva y el régimen de protección se aplica también a los elementos de interés que aparezcan con posterioridad:",
    o: ["Incluso si forman parte de edificios, recintos, zonas o elementos no incluidos en el Catálogo.",
        "A condición de que formen parte de edificios, recintos, zonas o elementos incluidos en el Catálogo.",
        "Una vez incorporados a la ficha del edificio, recinto, zona o elemento mediante su modificación.",
        "Incluso en edificios no incluidos en el Catálogo, salvo que se sitúen en recintos o zonas arqueológicas."],
    c: 0, exp: "Catálogo del Plan Municipal, Normativa General, art. 4: la descripción de las fichas «no se considera definitiva, por cuanto pueden existir otros» elementos de interés, y «Las determinaciones de protección previstas en esta normativa se aplicarán a todos los elementos de interés que pudieran ponerse de manifiesto con posterioridad a la elaboración de este Catálogo, incluso en el caso de que formen parte de edificios, recintos, zonas arqueológicas o elementos no incluidos en el Catálogo». La b) invierte el alcance y lo limita a lo catalogado; la c) añade una modificación previa de la ficha que el artículo no exige; la d) introduce una excepción para recintos y zonas, que el artículo menciona expresamente. En la misma línea, el art. 45 obliga a proteger los elementos de interés que aparezcan durante la consulta, la licencia o la obra y a comunicar los hallazgos al Ayuntamiento." },
  { id: "E54-10", tema: "E54", subtema: "Actuaciones permitidas, autorizables y prohibidas", tipo: "LIT",
    q: "Según el artículo 7 de la Normativa General del Catálogo del Plan Municipal de Pamplona (Texto Refundido aprobado por Acuerdo de la Comisión de Ordenación del Territorio de 18 de diciembre de 2002), en las actuaciones autorizables:",
    o: ["La licencia depende, con carácter general, de que en la consulta previa no se emita informe técnico desfavorable por incompatibilidad con la protección.",
        "La licencia depende, caso a caso, de que en la consulta previa se consideren compatibles con la conservación de los valores.",
        "La licencia depende, caso a caso, de que el Plan Especial del ámbito las considere compatibles con la conservación de los valores.",
        "La licencia depende, caso a caso, de que en la consulta previa se consideren necesarias para la conservación de los valores."],
    c: 1, exp: "Catálogo del Plan Municipal, Normativa General, art. 7.3: «La concesión de licencia para las actuaciones autorizables dependerá, en cada caso, de que en el trámite de consulta previa se consideren compatibles con la conservación de los valores del edificio». La a) describe el régimen de las PERMITIDAS (art. 7.2: «obtendrán licencia, salvo que, excepcionalmente, en el trámite de consulta previa reciban un informe técnico municipal desfavorable»); la c) cambia la consulta previa por un Plan Especial, y la d) exige que sean «necesarias» y no «compatibles». Las PROHIBIDAS no obtienen licencia (art. 7.4)." },
  { id: "E54-11", tema: "E54", subtema: "Recintos", tipo: "AFIRM",
    q: "De conformidad con la Normativa General del Catálogo del Plan Municipal de Pamplona (Texto Refundido aprobado por Acuerdo de la Comisión de Ordenación del Territorio de 18 de diciembre de 2002), señale la respuesta CORRECTA sobre los recintos:",
    o: ["Lo relevante para definir un recinto es su extensión, más que el carácter que imprime al conjunto.",
        "Los edificios catalogados de un recinto quedan sujetos a la normativa del recinto y no a la suya propia.",
        "Las actuaciones que afecten al carácter del recinto exigen la redacción de un Plan Especial de todo su ámbito.",
        "Se prohíbe con carácter general la reforma o ampliación de las edificaciones existentes en el recinto."],
    c: 2, exp: "Catálogo del Plan Municipal, Normativa General, art. 15.4: «Las actuaciones parciales de intervención en los recintos y áreas libres catalogados que pudieran afectar al carácter o integridad de los mismos, deberán sujetarse a los criterios emanados de un plan especial de todo el ámbito», sin cuya aprobación solo se autorizan las que contempla el Catálogo y las tareas ordinarias de mantenimiento: la c) es la correcta. La a) invierte el art. 11: «Lo relevante para su inclusión en este Catálogo no es su extensión, sino el carácter que el recinto imprime a las construcciones y espacios libres situados en su ámbito». La b) contradice el art. 14: los edificios o elementos contenidos en los recintos «quedarán sujetos a su propia normativa general y particular si aparecen catalogados como tales». La d) contradice el art. 15.2: «Se permite la reforma y ampliación de las construcciones existentes en estas áreas»; lo que se prohíbe con carácter general es construir NUEVAS edificaciones, salvo pequeños pabellones (art. 15.3)." },
  { id: "E54-12", tema: "E54", subtema: "Elementos: clasificación", tipo: "SEL",
    q: "Conforme a la clasificación de los elementos catalogados en la Normativa General del patrimonio edificado del Catálogo del Plan Municipal de Pamplona (Texto Refundido aprobado por Acuerdo de la Comisión de Ordenación del Territorio de 18 de diciembre de 2002), ¿cuál de los siguientes figura entre los elementos no vinculados a la edificación?",
    o: ["Los escudos de armas.",
        "Las alineaciones arboladas.",
        "Las askas.",
        "Los patios de manzana del Casco Viejo."],
    c: 2, exp: "Catálogo del Plan Municipal, Normativa General, art. 32 (redacción dada por la modificación aprobada definitivamente por el Pleno el 03-07-2025, BON n.º 155, de 05-08-2025): «B. Elementos no vinculados a la edificación -ENVE-: 1. Puentes, 2. Cruceros, 3. Fuentes, 4. Monumentos, 5. Mobiliario urbano, 6. Askas/abrevaderos, 7. Pabellones, 8. Panteones/Cementerio, 9. Elementos de la urbanización». Los escudos de armas son elementos VINCULADOS a la edificación (art. 32.A: «1. Escudos de armas, 2. Varios»); las alineaciones arboladas son una categoría del patrimonio natural (art. 5 de su Normativa), no del edificado, y los patios de manzana del Casco Viejo forman parte del Área A de las zonas arqueológicas (art. 10)." },
  { id: "E54-13", tema: "E54", subtema: "Glosario de obras", tipo: "DEF",
    q: "De acuerdo con el glosario de tipos de obras del Catálogo del Plan Municipal de Pamplona, la recuperación tipológica consiste en:",
    o: ["Devolver el edificio, total o parcialmente, a su estado primitivo, incluidos los elementos de interés aportados a lo largo de su historia.",
        "Restituir la traza u organización espacial del edificio parcialmente perdidas.",
        "Alterar, total o parcialmente, el trazado u organización espacial del edificio.",
        "Volver a levantar un edificio o parte desaparecido cuyas características se conocen, fiel a su origen."],
    c: 1, exp: "Catálogo del Plan Municipal, Normativa General, art. 8 (glosario): la RECUPERACIÓN TIPOLÓGICA es la «Intervención en un edificio para restituir la traza o la organización espacial parcialmente perdidas». La a) es la RESTITUCIÓN («Intervención en un edificio para devolverlo, en todo o en parte, a su estado primitivo, incluyendo en esta denominación, los elementos de interés aportados a lo largo de su historia»); la c) es la REESTRUCTURACIÓN («Alteración, total o parcial, del trazado o la organización espacial de un edificio o elemento»), y la d) es la RECONSTRUCCIÓN («Intervención que pretende volver a levantar un edificio o parte de él, desaparecido pero cuyas características se conocen, de manera fiel a su situación original»)." },
  { id: "E54-14", tema: "E54", subtema: "Patrimonio natural: grados 1 y 2", tipo: "COMB2",
    q: "Según la Normativa del patrimonio natural del Catálogo del Plan Municipal de Pamplona (Texto Refundido aprobado por Acuerdo de la Comisión de Ordenación del Territorio de 18 de diciembre de 2002), ¿qué régimen tiene la ocupación del espacio de proyección de la copa de un árbol aislado con pavimentos, aparcamiento o construcciones, según esté protegido en grado 1 o en grado 2?",
    o: ["En grado 1, prohibida; en grado 2, autorizable.",
        "En grado 1, prohibida; en grado 2, permitida.",
        "En grado 1, autorizable; en grado 2, permitida.",
        "En grado 1, autorizable; en grado 2, autorizable."],
    c: 0, exp: "Catálogo del Plan Municipal, Normativa del patrimonio natural: art. 9.1 (árboles aislados de grado 1), «Se prohíbe la ocupación del espacio de proyección de su copa sobre el suelo por pavimentaciones, zonas de aparcamiento, construcciones o cualquier otra ocupación que pueda suponer daño real o potencial al ejemplar»; art. 10.1 (grado 2), «Podrán autorizarse la ocupación del espacio de proyección de la copa sobre el suelo por pavimentaciones, zonas de aparcamiento, construcciones, etc..., así como la ejecución de nuevas plantaciones en las proximidades del ejemplar, siempre que no supongan perjuicio para el mismo». Por tanto, prohibida en grado 1 y autorizable en grado 2: la a). Ni es autorizable en grado 1 (c y d) ni está permitida sin más en grado 2 (b y c). En grado 2, además, la tala solo se autoriza con informe técnico de precariedad o riesgo a corto plazo." },
  { id: "E54-15", tema: "E54", subtema: "Patrimonio natural: categorías", tipo: "LISTA",
    q: "Indique las categorías en que clasifica el patrimonio natural la Normativa del patrimonio natural del Catálogo del Plan Municipal de Pamplona (Texto Refundido aprobado por Acuerdo de la Comisión de Ordenación del Territorio de 18 de diciembre de 2002):",
    o: ["Árboles aislados, parques y jardines, y espacios naturales.",
        "Árboles aislados, parques y jardines, y alineaciones arboladas.",
        "Monumentos naturales, jardines y alineaciones arboladas.",
        "Árboles aislados, espacios libres y alineaciones arboladas."],
    c: 1, exp: "Catálogo del Plan Municipal, Normativa del patrimonio natural, artículo 5: «Los elementos que constituyen el patrimonio natural se clasifican, de acuerdo con su tipología, en varios grupos: 1. Árboles aislados [...] 2. Parques y jardines [...] 3. Alineaciones arboladas» (las de gran porte, que conectan los parques y jardines entre sí y con los espacios «naturales» no urbanos). Los espacios naturales y los monumentos naturales remiten a la protección complementaria de la Ley Foral 9/1996, de Espacios Naturales de Navarra (art. 2; la Sequoia del INAP está clasificada como Monumento Natural MN-25), y los espacios libres son la red que el Catálogo quiere reconocer, no una categoría." },
  { id: "E54-16", tema: "E54", subtema: "Elementos vinculados a la edificación", tipo: "META",
    q: "Conforme a lo establecido en el artículo 35 de la Normativa General del Catálogo del Plan Municipal de Pamplona (Texto Refundido aprobado por Acuerdo de la Comisión de Ordenación del Territorio de 18 de diciembre de 2002), en los elementos catalogados vinculados a la edificación, como los escudos de armas:",
    o: ["Podrá autorizarse excepcionalmente su traslado cuando se considere debidamente justificado.",
        "Las intervenciones deberán ajustarse a las técnicas específicas de rehabilitación.",
        "La rehabilitación o sustitución de la fachada se supeditará a su puesta en valor.",
        "Las respuestas a) y c) son correctas."],
    c: 3, exp: "Catálogo del Plan Municipal, Normativa General, art. 35 (normas de protección de los elementos vinculados a la edificación): 35.1, no se permite modificar su emplazamiento salvo para volver a su posición original u otra anterior documentada, cuando sea necesario desmontarlos por razón de obras u otros motivos, y «podrá autorizarse excepcionalmente su traslado cuando se considere debidamente justificado» (la a) es literal); 35.5, «la rehabilitación o sustitución de una fachada que contenga elementos catalogados se supeditará a su puesta en valor, evitando el deterioro de los mismos» (la c) es literal). Por eso la correcta es la d). La b) es falsa: según el art. 35.4 las intervenciones deben ajustarse a las técnicas específicas de RESTAURACIÓN, no de rehabilitación. El art. 35.2 permite además modificar el emplazamiento en la fachada cuando sea necesario desmontarlo, siempre que no se alteren sus características ni su función." },
  // ---------- 05-11-2026 · LOTE DE 30 PREGUNTAS DIFÍCILES (E54-17 a E54-46) ----------
  // Añadidas para llevar el tema al nivel de los tribunales navarros (Zizur Mayor 2026, ⅔; Navarra 2026, ⅓): dato
  // exacto, órgano, excepción y diferencias entre grados o entre las dos normativas del Catálogo. Fuente única:
  // temas/E_Tema54.txt con las correcciones de src/data/textosTemas/E54.js (Normativa General del patrimonio edificado,
  // arts. 1-49, y Normativa del patrimonio natural, arts. 1-15, literales; arts. 32 y 36 en la redacción de la
  // modificación aprobada por el Pleno el 03-07-2025, BON n.º 155, de 05-08-2025, vigente a la convocatoria, BON 21-05-2026).
  // Dos bloques de 15 con la mezcla de GUIA_PREGUNTAS.md, sección 2 bis:
  //   Bloque 1 (E54-17 a 31): 3 META (17 «a) y c)» correcta, 18 «Todas» correcta, 19 «Ninguna» falsa), 3 DATO (20, 21, 22),
  //   2 NEG (23 INCORRECTA, 24 «no corresponde»), LISTA 25, LIT 26, AFIRM 27, SEL 28, DEF 29, ALCANCE 30 y COMB2 31.
  //   Bloque 2 (E54-32 a 46): 3 META (32 «b) y c)» correcta, 33 «Ninguna» falsa, 34 «a) y c)» correcta), 3 DATO (35, 36, 37),
  //   2 NEG (38 INCORRECTA, 39 «no corresponde»), LISTA 40, LIT 41, AFIRM 42, SEL 43, DEF 44, ALCANCE 45 y SUP 46.
  // Artículos. Normativa General: 8 (reedificación y rehabilitación), 12, 15.1, 19.3, 20, 21.2, 22, 24 (24.2-24.4, 24.7 y
  // 24.10), 26 (26.5 y 26.11-26.14), 28.10, 29.2, 30.5, 30.11, 33.3 y 34, 36.4, 42.7, 42.8, 43 (43.2-43.5), 45 y 48.
  // Normativa del patrimonio natural: 8, 9.1, 9.2, 10.2, 10.3, 11, 12 y 15. Letra correcta del lote: A 7, B 8, C 7, D 8.
  // No se preguntan la estadística de la Memoria, el marco legal derogado (LF 10/1994, DF 85/1995) ni los recuentos del
  // art. 36.4 (puentes, fuentes, cruceros, askas).
  { id: "E54-17", tema: "E54", subtema: "Edificios: normas comunes a los tres grados", tipo: "META",
    q: "Conforme a lo establecido en el artículo 24.10 de la Normativa General del Catálogo del Plan Municipal de Pamplona (Texto Refundido aprobado por Acuerdo de la Comisión de Ordenación del Territorio de 18 de diciembre de 2002), en las fachadas protegidas de los edificios catalogados, cualquiera que sea su grado, se prohíbe:",
    o: ["El cierre de balcones y terrazas.",
        "La fijación de mobiliario urbano.",
        "La instalación de marquesinas.",
        "Las respuestas a) y c) son correctas."],
    c: 3, exp: "Catálogo del Plan Municipal, Normativa General, art. 24.10 (normas comunes a los tres grados de protección): «En las fachadas protegidas se prohíbe: • El cierre de balcones y terrazas. • La implantación de las instalaciones propias del edificio en las fachadas, salvo bajantes de pluviales. • La instalación de antenas en las fachadas. • La instalación de marquesinas». La a) y la c) son literales, de modo que la correcta es la d). La b) es falsa: el mobiliario urbano no está en esa lista; según el art. 24.8, «Podrá autorizarse la colocación de elementos de mobiliario urbano e instalaciones de servicio público fijados a las fachadas». Ojo también a la salvedad de la lista: las bajantes de pluviales sí pueden ir en la fachada." },
  { id: "E54-18", tema: "E54", subtema: "Elementos vinculados a la edificación", tipo: "META",
    q: "Según la Normativa General del Catálogo del Plan Municipal de Pamplona (Texto Refundido aprobado por Acuerdo de la Comisión de Ordenación del Territorio de 18 de diciembre de 2002), los elementos catalogados vinculados a la edificación (EVE):",
    o: ["Forman parte inseparable de la edificación, aunque, como los escudos, puedan provenir de otras edificaciones.",
        "Se catalogan sin que ello suponga la catalogación de la edificación en la que se integran.",
        "Aparecen recogidos en las fichas correspondientes de los edificios en los que se encuentran.",
        "Todas las respuestas anteriores son correctas."],
    c: 3, exp: "Catálogo del Plan Municipal, Normativa General, art. 34.1: los elementos vinculados a la edificación «forman parte inseparable de la misma, aunque como en el caso de los escudos, puedan provenir de otras edificaciones»; art. 34.2: «La catalogación de un elemento no supone la catalogación de la edificación en que se integra»; art. 33.3: «Los elementos vinculados a la edificación -EVE- aparecen recogidos en las fichas correspondientes de los edificios en los que se encuentran» (no tienen ficha propia, a diferencia de los elementos no vinculados, que según el art. 38.1 aparecen cada uno «recogido en una ficha de Catálogo propia»). Las tres afirmaciones son literales, así que la correcta es la d)." },
  { id: "E54-19", tema: "E54", subtema: "Procedimiento: zonas arqueológicas", tipo: "META",
    q: "De conformidad con el artículo 42.7 de la Normativa General del Catálogo del Plan Municipal de Pamplona (Texto Refundido aprobado por Acuerdo de la Comisión de Ordenación del Territorio de 18 de diciembre de 2002), las medidas de excavación o catas arqueológicas previas a la licencia de obras que afecten al subsuelo, previstas para las áreas A y B, se aplican a la excavación de zanjas:",
    o: ["Cuando haya indicios concluyentes de restos arqueológicos, su anchura exceda 1 m y su desarrollo supere la longitud de una manzana de casas.",
        "Cuando haya indicios concluyentes de restos arqueológicos, o su anchura exceda 1 m, o su desarrollo supere la longitud de una manzana de casas.",
        "Cuando su excavación elimine los niveles actuales de pavimento y sus preparaciones, como en las demás obras que afectan al subsuelo.",
        "Ninguna de las respuestas anteriores es correcta."],
    c: 0, exp: "Catálogo del Plan Municipal, Normativa General, art. 42.7: «Las medidas y obligaciones señaladas en los puntos 2 y 3 del presente artículo, serán aplicables siempre que se eliminen los niveles actuales de pavimento y sus preparaciones. En aras de la operatividad, esta consideración no será aplicable a la excavación de zanjas, salvo que existan indicios concluyentes de la presencia de restos arqueológicos, su anchura exceda 1 m. y su desarrollo supere la longitud de una manzana de casas. En cualquier caso será de aplicación lo dispuesto en el artículo 45 de este Catálogo». Las tres condiciones de la salvedad van unidas por «y» y son acumulativas: la a) es la correcta. La b) las convierte en alternativas; la c) aplica a las zanjas la regla general de la eliminación del pavimento y sus preparaciones, que el artículo excluye precisamente para ellas. Como la a) es correcta, la d) es falsa." },
  { id: "E54-20", tema: "E54", subtema: "Edificios: parcela de edificios catalogados", tipo: "DATO",
    q: "Conforme a lo establecido en el artículo 21.2 de la Normativa General del Catálogo del Plan Municipal de Pamplona (Texto Refundido aprobado por Acuerdo de la Comisión de Ordenación del Territorio de 18 de diciembre de 2002), las licencias de segregación o agregación de parcelas solo se concederán si no implican la ejecución de obras que afecten negativamente a los edificios catalogados que contengan, cuando estos edificios estén catalogados en:",
    o: ["Solo el grado 1.",
        "Los grados 1 y 2.",
        "Los grados 2 y 3.",
        "Los tres grados."],
    c: 1, exp: "Catálogo del Plan Municipal, Normativa General, art. 21.2: «Las licencias de segregación o agregación de parcelas que contengan edificios catalogados en los grados 1 y 2, sólo se concederán si la segregación o agregación no implican la ejecución de obras que afecten negativamente a los edificios catalogados». El art. 21.1 se ciñe también a los grados 1 ó 2: la autorización de obras en cualquier otro edificio de la parcela o en la parcela misma se supedita a la protección de los valores del edificio catalogado. La regla no se limita al grado 1 ni alcanza al grado 3; la que vale para los tres grados («en cualquiera de sus grados») es la del art. 22, sobre la ruina." },
  { id: "E54-21", tema: "E54", subtema: "Recintos", tipo: "DATO",
    q: "Según el artículo 12 de la Normativa General del Catálogo del Plan Municipal de Pamplona (Texto Refundido aprobado por Acuerdo de la Comisión de Ordenación del Territorio de 18 de diciembre de 2002), ¿en qué recinto catalogado se incluye el Archivo General?",
    o: ["R1, Recinto amurallado.",
        "R3, Catedral y Palacio Arzobispal.",
        "R4, Palacio de Navarra.",
        "R5, Plaza de las Recoletas."],
    c: 2, exp: "Catálogo del Plan Municipal, Normativa General, art. 12: «R4: Palacio de Navarra. Comprende el Palacio de Navarra, Archivo General y jardines». El R1 (Recinto amurallado) comprende el perímetro amurallado de la ciudad en los lados N-E-W y los baluartes y fuertes del lado sur; el R3 (Catedral y Palacio Arzobispal), la plaza de San José, la Catedral, atrio, claustro, patio de Arcedianato, huerta y palacio Arzobispal, y el R5 es la plaza de las Recoletas, presidida por el convento de clausura de las Agustinas Recoletas. El quinto es el R2, Ciudadela (Ciudadela, baluartes, glacis y parque de la Vuelta del Castillo)." },
  { id: "E54-22", tema: "E54", subtema: "Patrimonio natural: infracciones", tipo: "DATO",
    q: "De acuerdo con la Normativa del patrimonio natural del Catálogo del Plan Municipal de Pamplona (Texto Refundido aprobado por Acuerdo de la Comisión de Ordenación del Territorio de 18 de diciembre de 2002), ¿conforme a qué determinaciones se valoran las infracciones cometidas contra los bienes del patrimonio natural protegido?",
    o: ["Las Normas Granada.",
        "Las Ordenanzas Municipales.",
        "La Carta de Florencia.",
        "La Ley 16/1985."],
    c: 0, exp: "Catálogo del Plan Municipal, Normativa del patrimonio natural, artículo 15: «Las valoraciones que se realicen como consecuencia de las infracciones cometidas contra los bienes del patrimonio natural protegido se valorarán conforme a las determinaciones fijadas por las Normas Granada -UNESCO 1990-, sin perjuicio de la que proceda aplicar en el caso de patrimonio natural protegido por la legislación autonómica (L.F. 9/1.996 de Espacios Naturales de Navarra y disposiciones que la desarrollan)». Las Ordenanzas Municipales son las que sirven, según el artículo 7, para SANCIONAR las acciones que dañen el arbolado, no para valorar las infracciones; la Ley 16/1985, del Patrimonio Histórico Español, forma parte del marco legal superior (artículo 2), y la Carta de Florencia (jardines históricos) no se cita en el Catálogo." },
  { id: "E54-23", tema: "E54", subtema: "Patrimonio natural: instalaciones temporales", tipo: "NEG",
    q: "Señale la respuesta INCORRECTA en relación con lo dispuesto en el artículo 11 de la Normativa del patrimonio natural del Catálogo del Plan Municipal de Pamplona (Texto Refundido aprobado por Acuerdo de la Comisión de Ordenación del Territorio de 18 de diciembre de 2002) sobre las instalaciones temporales:",
    o: ["Podrán autorizarse en las proximidades de árboles aislados o alineaciones cuando no afecten negativamente a su integridad.",
        "La licencia se solicitará previamente con información detallada que, si afecta a árboles aislados, incluirá fotografías recientes.",
        "Para conceder la licencia será preciso un informe favorable referido a su repercusión en los elementos catalogados.",
        "La reparación del deterioro que produzcan corresponderá al Ayuntamiento, que repercutirá su coste al solicitante."],
    c: 3, exp: "Catálogo del Plan Municipal, Normativa del patrimonio natural, artículo 11: «Podrán autorizarse instalaciones provisionales en las proximidades de árboles aislados o alineaciones, o en el ámbito de parques y jardines, cuando no afecten negativamente a su integridad ni comprometan su mantenimiento», con licencia previa, «adjuntando a la solicitud información detallada sobre la instalación que, si afectan a árboles aislados, incluirá fotografías recientes de los mismos», y con un «informe favorable que se refiera específicamente a la repercusión de la instalación en los elementos catalogados». La d) es la INCORRECTA: «La reparación del deterioro que pueda producirse en el elemento catalogado como consecuencia de la instalación será responsabilidad del solicitante, que deberá realizar a su costa las obras precisas en el plazo que el Ayuntamiento fije para ello»; el Ayuntamiento solo ejecuta esas obras, pasando el cargo al obligado, si el solicitante no cumple. La a), la b) y la c) reproducen el artículo." },
  { id: "E54-24", tema: "E54", subtema: "Edificios: grado 1", tipo: "NEG",
    q: "Conforme a lo establecido en el artículo 26 de la Normativa General del Catálogo del Plan Municipal de Pamplona (Texto Refundido aprobado por Acuerdo de la Comisión de Ordenación del Territorio de 18 de diciembre de 2002), no corresponde a las normas de actuación en los edificios protegidos en grado 1:",
    o: ["Podrá autorizarse la sustitución de los elementos estructurales de la cubierta sin variar su expresión exterior.",
        "Podrán autorizarse cambios en la distribución interior que no afecten a su organización espacial y tipológica.",
        "Podrán autorizarse pequeñas modificaciones en la disposición y el tamaño de los huecos de fachada.",
        "Podrán autorizarse las obras necesarias para mejorar la accesibilidad del edificio."],
    c: 2, exp: "Catálogo del Plan Municipal, Normativa General, art. 26.5 (grado 1): «Se mantendrá la composición de las fachadas y la disposición y tamaño de sus huecos. Podrá autorizarse su recuperación tipológica». Las «pequeñas modificaciones en la disposición y tamaño de los huecos que no desvirtúen la composición general» son autorizables en el grado 2 (art. 28.7), no en el grado 1: la c) es la que no corresponde. Las demás son del art. 26: 26.11, «Podrá autorizarse la sustitución de los elementos estructurales de la cubierta sin variar su expresión exterior» (la a); 26.12, «Podrán autorizarse cambios en la distribución interior del edificio cuando no afecten a su organización espacial y tipológica» (la b), y 26.13, «Podrán autorizarse las obras necesarias para mejorar la accesibilidad» (la d)." },
  { id: "E54-25", tema: "E54", subtema: "Patrimonio natural: parques y jardines de grado 1", tipo: "LISTA",
    q: "Conforme a la Normativa del patrimonio natural del Catálogo del Plan Municipal de Pamplona (Texto Refundido aprobado por Acuerdo de la Comisión de Ordenación del Territorio de 18 de diciembre de 2002), los parques y jardines protegidos en grado 1 son:",
    o: ["Jardines de la Taconera, Parque de la Media Luna y conjunto Ciudadela-Vuelta del Castillo.",
        "Jardines de la Taconera, Parque de la Media Luna y Jardín de la Diputación.",
        "Jardines de la Taconera, Plaza de los Fueros y Jardín de la Diputación.",
        "Conjunto Ciudadela-Vuelta del Castillo, Plaza de los Fueros y Jardín de la Diputación."],
    c: 1, exp: "Catálogo del Plan Municipal, Normativa del patrimonio natural, artículo 9.2 (parques y jardines de grado 1, «con alto interés natural e histórico-artístico, que además son elementos claves en la trama urbana de la ciudad»): «Son: - Jardines de la Taconera [...] - Parque de la Media Luna [...] - Jardín de la Diputación». El conjunto Ciudadela-Vuelta del Castillo y la Plaza de los Fueros están protegidos en grado 2 (artículo 10.2). Ojo: la Ciudadela es un recinto (R2) del patrimonio edificado, pero en el patrimonio natural el conjunto Ciudadela-Vuelta del Castillo es de grado 2." },
  { id: "E54-26", tema: "E54", subtema: "Edificios: contenido del Catálogo", tipo: "LIT",
    q: "Según el artículo 19.3 de la Normativa General del Catálogo del Plan Municipal de Pamplona (Texto Refundido aprobado por Acuerdo de la Comisión de Ordenación del Territorio de 18 de diciembre de 2002), en las fichas de Catálogo de los edificios, además de los datos de identificación y de una descripción escrita y gráfica, se especifican las determinaciones particulares que la catalogación impone en aquellos casos en que se considera necesario:",
    o: ["Matizar la aplicación de la normativa, ampliar el régimen de obras autorizado de forma general o destacar los elementos a proteger del edificio.",
        "Matizar la aplicación de la normativa, limitar el régimen de obras autorizado de forma general o destacar los usos compatibles con el edificio.",
        "Matizar la aplicación de la normativa, limitar el régimen de obras autorizado de forma general o destacar los elementos a proteger del edificio.",
        "Sustituir la aplicación de la normativa, limitar el régimen de obras autorizado de forma general o destacar los elementos a proteger del edificio."],
    c: 2, exp: "Catálogo del Plan Municipal, Normativa General, art. 19.3: «Fichas de Catálogo, donde, además de los datos de identificación, una descripción escrita y gráfica de los edificios, se especifican las determinaciones particulares que la catalogación impone en aquellos casos en que se considera necesario matizar la aplicación de la normativa, limitar el régimen de obras autorizado de forma general o destacar los elementos a proteger del edificio». La a) cambia «limitar» por «ampliar»; la b), «los elementos a proteger» por «los usos compatibles» (el uso se regula en el art. 23), y la d), «matizar» por «sustituir»." },
  { id: "E54-27", tema: "E54", subtema: "Procedimiento: consulta previa", tipo: "AFIRM",
    q: "De conformidad con el artículo 43 de la Normativa General del Catálogo del Plan Municipal de Pamplona (Texto Refundido aprobado por Acuerdo de la Comisión de Ordenación del Territorio de 18 de diciembre de 2002), señale la respuesta CORRECTA sobre la consulta previa en los expedientes de obras de edificios catalogados:",
    o: ["Su aprobación exime de adjuntar a la licencia la memoria de protección, salvo cambio de circunstancias.",
        "Debe obtener la aprobación de la Institución Príncipe de Viana para continuar el trámite de licencia.",
        "Las condiciones que se fijen en su aprobación tienen carácter orientativo para obtener la licencia.",
        "Una vez aprobada, la licencia se solicita siguiendo un trámite abreviado y no el general."],
    c: 0, exp: "Catálogo del Plan Municipal, Normativa General, art. 43.5: «La aprobación de la consulta previa eximirá de la obligación de adjuntar a la solicitud de licencia la memoria de protección mencionada en el artículo 40, salvo que los servicios técnicos municipales la exijan porque alguna circunstancia que afecte al edificio haya cambiado»: la a) es la correcta. La b) es falsa: según el art. 43.3, la consulta previa debe obtener la aprobación del ÓRGANO MUNICIPAL COMPETENTE; la Institución Príncipe de Viana da la autorización previa a las actuaciones en inmuebles de grado 1 y 2 situados en un ámbito B.I.C. (art. 43.1). La c) es falsa: «Las condiciones que pudieran establecerse en esa aprobación serán vinculantes y deberán cumplirse para poder obtener la licencia» (art. 43.3). La d) es falsa: «Una vez aprobada la consulta previa se podrá solicitar la licencia, siguiendo el trámite general» (art. 43.4)." },
  { id: "E54-28", tema: "E54", subtema: "Elementos no vinculados a la edificación", tipo: "SEL",
    q: "Conforme al artículo 36.4 de la Normativa General del Catálogo del Plan Municipal de Pamplona (Texto Refundido aprobado por Acuerdo de la Comisión de Ordenación del Territorio de 18 de diciembre de 2002), en su redacción vigente, ¿cuál de los siguientes se incluye entre los elementos de urbanización de los elementos no vinculados a la edificación?",
    o: ["Las askas o abrevaderos.",
        "Las barandillas.",
        "Las piezas de mobiliario de jardines.",
        "Los portales de murallas."],
    c: 1, exp: "Catálogo del Plan Municipal, Normativa General, art. 36.4, en la redacción dada por la modificación aprobada definitivamente por el Pleno el 03-07-2025 (BON n.º 155, de 05-08-2025): «9) Elementos de urbanización. Algunos elementos significativos de urbanización: escaleras, barandillas, farola monumental, pavimentación, etc.». La modificación añadió las barandillas a los ejemplos (ficha 9.1, «Modelo Barandilla Media Luna»). Las askas o abrevaderos tienen apartado propio («6) Askas/Abrevaderos»); las piezas de mobiliario de jardines y recintos históricos son el «5) Mobiliario urbano», y los portales de murallas están en «4) Monumentos»." },
  { id: "E54-29", tema: "E54", subtema: "Glosario de obras", tipo: "DEF",
    q: "Según el glosario de tipos de obras de la Normativa General del Catálogo del Plan Municipal de Pamplona (Texto Refundido aprobado por Acuerdo de la Comisión de Ordenación del Territorio de 18 de diciembre de 2002), se denomina reedificación:",
    o: ["El cambio de un edificio o parte de él por otro cuyas características pueden ser diferentes del original.",
        "La sustitución de un edificio o parte de él cuando el volumen resultante es similar al primitivo.",
        "La sustitución de partes o elementos de un edificio por otros de características similares a los originales.",
        "La intervención que pretende volver a levantar un edificio desaparecido cuyas características se conocen."],
    c: 1, exp: "Catálogo del Plan Municipal, Normativa General, art. 8 (glosario): «Reedificación: Sustitución de un edificio o parte de él cuando el volumen resultante es similar al primitivo». La a) es la SUSTITUCIÓN («Cambio de un edificio o parte de él por otro cuyas características pueden ser diferentes del original»); la c) es la REPOSICIÓN («Sustitución de partes o elementos de un edificio por otros que tengan características similares a los originales», en la que podrán autorizarse variantes actuales de los materiales y técnicas primitivos), y la d) es la RECONSTRUCCIÓN («Intervención que pretende volver a levantar un edificio o parte de él, desaparecido pero cuyas características se conocen, de manera fiel a su situación original»)." },
  { id: "E54-30", tema: "E54", subtema: "Edificios: ruina", tipo: "ALCANCE",
    q: "De acuerdo con la Normativa General del Catálogo del Plan Municipal de Pamplona (Texto Refundido aprobado por Acuerdo de la Comisión de Ordenación del Territorio de 18 de diciembre de 2002), las edificaciones catalogadas que fueran declaradas en ruina, de acuerdo con el procedimiento establecido por la Ley:",
    o: ["Deberán ser rehabilitadas a cargo de su propietario, cualquiera que sea su grado de protección.",
        "Deberán ser rehabilitadas a cargo de su propietario, si están catalogadas en los grados 1 o 2.",
        "Deberán ser rehabilitadas a cargo del Ayuntamiento, si están catalogadas en los grados 1 o 2.",
        "Podrán ser demolidas si están catalogadas en grado 3, al quedar sin efecto su catalogación."],
    c: 0, exp: "Catálogo del Plan Municipal, Normativa General, art. 22: «Las edificaciones catalogadas en cualquiera de sus grados y que fueran declaradas en ruina, de acuerdo con el procedimiento establecido por la Ley, deberán ser rehabilitadas a cargo de su propietario, manteniendo los elementos de valor existentes en el edificio, conforme a las previsiones del planeamiento». La regla vale para los tres grados: no se limita a los grados 1 y 2 (b) ni deja sin efecto la catalogación del grado 3 para permitir su demolición (d), y la rehabilitación corre a cargo del propietario, no del Ayuntamiento (c, que además la limita a los grados 1 y 2)." },
  { id: "E54-31", tema: "E54", subtema: "Patrimonio natural: consulta previa", tipo: "COMB2",
    q: "Según la Normativa del patrimonio natural del Catálogo del Plan Municipal de Pamplona (Texto Refundido aprobado por Acuerdo de la Comisión de Ordenación del Territorio de 18 de diciembre de 2002), ¿en qué expedientes de obras es preceptiva una consulta previa?",
    o: ["En los de cualquier iniciativa que afecten a bienes de grado 1.",
        "En los de cualquier iniciativa que afecten a bienes de grado 1 o 2.",
        "En los de iniciativa no municipal que afecten a bienes de grado 1 o 2.",
        "En los de iniciativa no municipal que afecten a bienes de grado 1."],
    c: 3, exp: "Catálogo del Plan Municipal, Normativa del patrimonio natural, artículo 12.1: «En la tramitación de expedientes de obras de iniciativa no municipal que afecten a bienes incluidos en el grado 1 será preceptiva una consulta previa», en la que el promotor presenta la memoria de protección y la documentación de la intervención; su aprobación por el órgano municipal competente es necesaria para seguir hacia la licencia y sus condiciones son vinculantes (artículo 12.2). Por tanto, iniciativa no municipal y grado 1: la d). No debe confundirse con el patrimonio edificado, donde la consulta previa es preceptiva en los grados 1 y 2 sin distinguir la iniciativa (art. 43.1 de la Normativa General)." },
  { id: "E54-32", tema: "E54", subtema: "Edificios: ampliaciones por grado", tipo: "META",
    q: "Conforme a lo establecido en los artículos 26, 28 y 30 de la Normativa General del Catálogo del Plan Municipal de Pamplona (Texto Refundido aprobado por Acuerdo de la Comisión de Ordenación del Territorio de 18 de diciembre de 2002), en materia de ampliaciones de los edificios catalogados:",
    o: ["En el grado 3 se prohíben las ampliaciones en altura.",
        "En el grado 1 se prohíben las ampliaciones en altura.",
        "En el grado 2 podrán autorizarse las ampliaciones en planta y en altura.",
        "Las respuestas b) y c) son correctas."],
    c: 3, exp: "Catálogo del Plan Municipal, Normativa General, art. 26.14 (grado 1): «Se prohíben las ampliaciones en altura. Podrán autorizarse, de manera excepcional, las ampliaciones en planta» (la b) es correcta); art. 28.10 (grado 2): «Podrán autorizarse las ampliaciones tanto en planta como en altura. Se prohíben las ampliaciones en altura que afecten negativamente a los valores y elementos de interés del edificio» (la c) es correcta); art. 30.5 (grado 3): «Se permiten las ampliaciones en planta siempre que no afecten negativamente a las fachadas catalogadas y a otros elementos de interés. Podrán autorizarse las ampliaciones en altura». La a) es falsa, porque en el grado 3 las ampliaciones en altura son autorizables. Correcta, la d)." },
  { id: "E54-33", tema: "E54", subtema: "Procedimiento: elementos de interés no catalogados", tipo: "META",
    q: "De acuerdo con el artículo 45 de la Normativa General del Catálogo del Plan Municipal de Pamplona (Texto Refundido aprobado por Acuerdo de la Comisión de Ordenación del Territorio de 18 de diciembre de 2002), en relación con los elementos de interés no considerados en el Catálogo:",
    o: ["Comunicado el hallazgo de un elemento de interés durante la obra, la Institución Príncipe de Viana se pronunciará sobre su conservación.",
        "Durante la consulta previa o la licencia, los servicios técnicos municipales podrán considerar justificadamente otros elementos de interés.",
        "La obligación de comunicar los hallazgos producidos durante la obra rige solo en las obras sobre bienes incluidos en el Catálogo.",
        "Ninguna de las respuestas anteriores es correcta."],
    c: 1, exp: "Catálogo del Plan Municipal, Normativa General, art. 45.1: además de los elementos de interés mencionados expresamente, «durante el trámite de consulta previa o en el de licencia, los servicios técnicos municipales podrán considerar justificadamente la existencia de otros y tenerlos en cuenta a la hora de aplicar el régimen de protección establecido»: la b) es la correcta y, por tanto, la d) es falsa. La a) es falsa: según el art. 45.3, una vez que el titular de la licencia pone el hallazgo en conocimiento del Ayuntamiento, con documentación fotográfica, «el Ayuntamiento se pronunciará sobre la exigencia o no de conservación de dicho elemento». La c) es falsa: el art. 45.4 extiende esa obligación a todos los elementos de interés que puedan aparecer «tanto en obras realizadas en los ámbitos, edificios o elementos relacionados en este Catálogo como en cualquier otra obra»." },
  { id: "E54-34", tema: "E54", subtema: "Recintos", tipo: "META",
    q: "Conforme a lo establecido en el artículo 15.1 de la Normativa General del Catálogo del Plan Municipal de Pamplona (Texto Refundido aprobado por Acuerdo de la Comisión de Ordenación del Territorio de 18 de diciembre de 2002), el trazado actual de los recintos catalogados será conservado sin merma de sus valores urbanos y paisajísticos, pero podrán autorizarse modificaciones cuando se busque:",
    o: ["La recuperación del trazado original en aquellas partes en las que hubiera sido alterado.",
        "La mejora de las condiciones de accesibilidad, habitabilidad o uso, si así se justifica en la consulta previa.",
        "La mejora de las condiciones de accesibilidad, habitabilidad o uso, si así se justifica en el Plan Especial.",
        "Las respuestas a) y c) son correctas."],
    c: 3, exp: "Catálogo del Plan Municipal, Normativa General, art. 15.1: «El trazado actual del recinto, entendido como las líneas maestras de su organización en el plano, será conservado sin merma de sus valores urbanos y paisajísticos. Podrán autorizarse modificaciones, cuando se busque la recuperación del trazado original en aquellas partes donde hubiera sido alterado o, si así se justifica en el Plan Especial correspondiente (vid. artículo 13), la mejora de las condiciones de accesibilidad, habitabilidad o uso». La a) y la c) son literales, así que la correcta es la d). La b) es falsa: la mejora de la accesibilidad, la habitabilidad o el uso tiene que justificarse en el Plan Especial, no en la consulta previa." },
  { id: "E54-35", tema: "E54", subtema: "Procedimiento: zonas arqueológicas", tipo: "DATO",
    q: "De conformidad con el artículo 42.8 de la Normativa General del Catálogo del Plan Municipal de Pamplona (Texto Refundido aprobado por Acuerdo de la Comisión de Ordenación del Territorio de 18 de diciembre de 2002), en los ámbitos delimitados como B.I.C., ¿quién autoriza expresamente, mediante resolución, destruir o alterar los elementos del Patrimonio Arqueológico que pudieran aparecer en el transcurso de una obra?",
    o: ["El órgano municipal competente.",
        "El Director General de Cultura.",
        "El Servicio Municipal de Arqueología.",
        "El técnico director de la excavación."],
    c: 1, exp: "Catálogo del Plan Municipal, Normativa General, art. 42.8: «En previsión del descubrimiento de restos arqueológicos de singular importancia y para asegurar el cumplimiento del punto 6 del presente artículo, será necesaria, en los ámbitos delimitados como B.I.C., la autorización expresa, mediante resolución del Director General de Cultura-Institución Príncipe de Viana, para destruir o alterar los elementos del Patrimonio Arqueológico que eventualmente pudieran aparecer en el transcurso de una obra». El órgano municipal competente aprueba la consulta previa (art. 43.3); el Servicio Municipal de Arqueología aún no existe (el art. 42.9 encarga la gestión a la Dirección General de Cultura «en tanto no se produzca» su creación), y el técnico competente dirige la excavación o las catas y redacta el estudio técnico (arts. 42.4 y 42.5), pero no autoriza destruir restos." },
  { id: "E54-36", tema: "E54", subtema: "Edificios: grado 3", tipo: "DATO",
    q: "Según el artículo 29.2 de la Normativa General del Catálogo del Plan Municipal de Pamplona (Texto Refundido aprobado por Acuerdo de la Comisión de Ordenación del Territorio de 18 de diciembre de 2002), en los edificios protegidos en grado 3, además de otros elementos que se mencionen en cada ficha, se consideran elementos de interés:",
    o: ["Todas las fachadas del edificio.",
        "La fachada principal del edificio.",
        "Las fachadas que den a espacio público.",
        "Las fachadas y la cubierta del edificio."],
    c: 2, exp: "Catálogo del Plan Municipal, Normativa General, art. 29.2: «Las fichas particulares identifican las partes y elementos de interés del edificio y señalan las determinaciones en orden a su conservación. Además de otros elementos que se mencionen en cada ficha, las fachadas que den a espacio público se consideran elementos de interés». No son todas las fachadas ni solo la principal, y la cubierta no se cita (las obras que afecten a la cubierta de un edificio de grado 3 hacen preceptiva la consulta previa, art. 43.2, pero eso no la convierte en elemento de interés)." },
  { id: "E54-37", tema: "E54", subtema: "Edificios: grados de protección", tipo: "DATO",
    q: "Conforme a la Normativa General del Catálogo del Plan Municipal de Pamplona (Texto Refundido aprobado por Acuerdo de la Comisión de Ordenación del Territorio de 18 de diciembre de 2002), la protección de los edificios catalogados se establece en tres grados atendiendo a:",
    o: ["Su extensión e intensidad.",
        "Su valor histórico y artístico.",
        "Su antigüedad y estado de conservación.",
        "Su localización en la trama urbana."],
    c: 0, exp: "Catálogo del Plan Municipal, Normativa General, art. 20: «La protección de los edificios catalogados se establece en tres grados atendiendo a su extensión e intensidad. Los grados 1 y 2 protegen al edificio en su conjunto mientras que el grado 3 asigna la protección sólo a determinados elementos arquitectónicos relevantes, generalmente la fachada, descritos en la ficha particular». El artículo no da como criterio el valor histórico o artístico, la antigüedad, el estado de conservación ni la localización; la Memoria del Catálogo (I.7) insiste en que el grado no es un índice del valor del edificio, sino la categoría ligada al régimen de obras más adecuada para él." },
  { id: "E54-38", tema: "E54", subtema: "Edificios: normas comunes a los tres grados", tipo: "NEG",
    q: "Señale la respuesta INCORRECTA en relación con lo dispuesto en el artículo 24 de la Normativa General del Catálogo del Plan Municipal de Pamplona (Texto Refundido aprobado por Acuerdo de la Comisión de Ordenación del Territorio de 18 de diciembre de 2002) sobre las normas comunes a los tres grados de protección de los edificios:",
    o: ["Se permiten las obras necesarias para la conservación de los edificios y su consolidación.",
        "Se permiten las obras necesarias para la implantación y el mantenimiento de las instalaciones e infraestructuras.",
        "Se permiten las obras necesarias para el cumplimiento de la normativa sobre evacuación y protección contra incendios.",
        "Se permiten las obras de restitución, incluido el derribo de los añadidos sin valor que especifiquen las fichas."],
    c: 2, exp: "Catálogo del Plan Municipal, Normativa General, art. 24.7: «Podrán autorizarse las obras necesarias para el cumplimiento de la normativa vigente sobre evacuación y protección contra incendios»: son AUTORIZABLES, no permitidas, y por eso la c) es la INCORRECTA (según el art. 7, las permitidas obtienen licencia salvo informe técnico desfavorable excepcional y las autorizables dependen de que en la consulta previa se consideren compatibles con los valores del edificio). Las demás son literales: 24.3, «Se permiten las obras necesarias para la conservación de los edificios y su consolidación»; 24.2, «Se permiten las obras necesarias para la implantación y el mantenimiento de las instalaciones e infraestructuras», y 24.4, «Se permiten las obras de restitución, incluyendo el derribo de aquellos añadidos sin valor que se especifiquen en las fichas particulares y la reconstrucción de partes o elementos de valor desaparecidos»." },
  { id: "E54-39", tema: "E54", subtema: "Patrimonio natural: alineaciones arboladas", tipo: "NEG",
    q: "De acuerdo con la Normativa del patrimonio natural del Catálogo del Plan Municipal de Pamplona (Texto Refundido aprobado por Acuerdo de la Comisión de Ordenación del Territorio de 18 de diciembre de 2002), no corresponde al régimen de las alineaciones arboladas protegidas:",
    o: ["Se permiten las labores de mantenimiento y mejora de las plantaciones y siembras.",
        "Serán autorizables los apeos y los cambios de especies de las plantaciones.",
        "Es autorizable la tala de algunos de sus elementos si se justifica por obras en el subsuelo.",
        "Es autorizable la reducción del tamaño de los alcorques si se justifica por obras en el subsuelo."],
    c: 3, exp: "Catálogo del Plan Municipal, Normativa del patrimonio natural, artículo 10.3 (alineaciones arboladas, grado 2): «Se permiten las labores de mantenimiento y mejora de las plantaciones y siembras. Serán autorizables los apeos y cambios de especies, así como la tala de algunos de los elementos que las componen si se justifica su necesidad por obras en el subsuelo. No se permite la disminución del tamaño de los alcorques, ni aquellas acciones que supongan una merma en la posibilidad de desarrollo de las especies arbóreas de mediano y gran porte». La d) no corresponde: la reducción de los alcorques no se permite, ni siquiera por obras en el subsuelo, que solo justifican la tala de algunos elementos. La a), la b) y la c) son literales." },
  { id: "E54-40", tema: "E54", subtema: "Patrimonio natural: árboles aislados de grado 1", tipo: "LISTA",
    q: "Conforme a la Normativa del patrimonio natural del Catálogo del Plan Municipal de Pamplona (Texto Refundido aprobado por Acuerdo de la Comisión de Ordenación del Territorio de 18 de diciembre de 2002), los árboles aislados protegidos en grado 1 son:",
    o: ["Sequoia de Diputación, Sequoia del patio del INAP y Tejo junto al monumento a Navarro Villoslada.",
        "Sequoia de Diputación, Sequoia del patio del INAP y Sophora de la Plaza de Recoletas.",
        "Sequoia del patio del INAP, Sophora de la Plaza de Recoletas y Magnolio de la Mancomunidad de Aguas.",
        "Tejo junto al monumento a Navarro Villoslada, Sophora de la Plaza de Recoletas y Magnolio de la Mancomunidad de Aguas."],
    c: 1, exp: "Catálogo del Plan Municipal, Normativa del patrimonio natural, artículo 9.1 (árboles aislados de grado 1): «Son: 1.- Sequoia de Diputación. 2.- Sequoia del patio del INAP (antigua Escuela de Magisterio). Protección complementaria: MN-25 (O.F.926/1996, de 6 de septiembre). 3.- Sophora de la Plaza de Recoletas». El Tejo junto al monumento a Navarro Villoslada (Hotel Tres Reyes) y el Magnolio del patio de la Mancomunidad de Aguas (General Chinchilla n 7) son árboles aislados de grado 2 (artículo 10.1), como los Cedros de Aranzadi o el Tilo de Oscus." },
  { id: "E54-41", tema: "E54", subtema: "Edificios: grado 3", tipo: "LIT",
    q: "Según el artículo 30.11 de la Normativa General del Catálogo del Plan Municipal de Pamplona (Texto Refundido aprobado por Acuerdo de la Comisión de Ordenación del Territorio de 18 de diciembre de 2002), en los edificios protegidos en grado 3:",
    o: ["La protección de un local comercial catalogado se extiende a todos los elementos del mobiliario y la rotulación originales que aparecen formando parte del diseño del conjunto.",
        "La protección de un local comercial catalogado se extiende a los elementos del mobiliario y la rotulación originales que aparecen descritos expresamente en su ficha particular.",
        "La protección de un local comercial catalogado se extiende a todos los elementos del mobiliario original que aparecen formando parte del diseño del conjunto, salvo la rotulación.",
        "La protección de un local comercial catalogado se extiende a todos los elementos del mobiliario y la rotulación, originales o añadidos, que formen parte del conjunto."],
    c: 0, exp: "Catálogo del Plan Municipal, Normativa General, art. 30.11: «La protección de un local comercial catalogado se extiende a todos los elementos del mobiliario y la rotulación originales que aparecen formando parte del diseño del conjunto». La b) la limita a lo descrito en la ficha (el art. 24.9 protege los bienes muebles de interés integrados en el edificio «aparezcan o no recogidos en las fichas particulares»); la c) excluye la rotulación, que el artículo protege expresamente, y la d) añade los elementos añadidos, cuando la norma se refiere solo a los ORIGINALES. En la misma línea, el art. 30.10 obliga a conservar y poner en valor los elementos decorativos y el mobiliario originales, «supeditando lo nuevo a los valores existentes»." },
  { id: "E54-42", tema: "E54", subtema: "Patrimonio natural: grados 1 y 2", tipo: "AFIRM",
    q: "De conformidad con la Normativa del patrimonio natural del Catálogo del Plan Municipal de Pamplona (Texto Refundido aprobado por Acuerdo de la Comisión de Ordenación del Territorio de 18 de diciembre de 2002), señale la respuesta CORRECTA sobre sus grados de protección:",
    o: ["El grado 2 se aplica a los ejemplares de interés y a los elementos y espacios con importante interés natural, histórico o de otro tipo.",
        "El grado 1 se aplica a los ejemplares de alto valor y a los elementos y espacios de importancia por su posición en la red de espacios libres.",
        "El grado 2 se aplica a los ejemplares de interés y a los elementos y espacios de importancia por su posición en la red de espacios libres.",
        "En el grado 1, además del mantenimiento, mejora y recuperación, se contemplan actuaciones de rehabilitación y/o adaptación."],
    c: 2, exp: "Catálogo del Plan Municipal, Normativa del patrimonio natural, artículo 8.2 (grado 2): «Se aplica a los ejemplares de interés y a los elementos y espacios de importancia por su posición en la red de espacios libres y naturales»: la c) es la correcta. Según el artículo 8.1, el grado 1 «Se aplica a los ejemplares considerados de alto valor y a elementos y espacios con importante interés natural, histórico o de otro tipo»: la a) atribuye al grado 2 los espacios del grado 1 y la b), al revés, lleva al grado 1 el criterio de la posición en la red. La d) es falsa: la rehabilitación y/o adaptación es propia del grado 2 («Además del mantenimiento, mejora y recuperación se contemplan actuaciones de rehabilitación y/o adaptación de los elementos o espacios, manteniendo el espíritu original»); en el grado 1 las actuaciones «se orientarán al mantenimiento o mejora de sus valores actuales y a la recuperación de sus características originales»." },
  { id: "E54-43", tema: "E54", subtema: "Planes especiales de protección", tipo: "SEL",
    q: "Conforme al artículo 48 de la Normativa General del Catálogo del Plan Municipal de Pamplona (Texto Refundido aprobado por Acuerdo de la Comisión de Ordenación del Territorio de 18 de diciembre de 2002), ¿cuál de las siguientes materias puede regular un plan especial de protección?",
    o: ["Las posibles ampliaciones en edificios catalogados.",
        "El grado de protección de los edificios catalogados.",
        "La delimitación de las zonas arqueológicas catalogadas.",
        "La relación de recintos incluidos en el Catálogo."],
    c: 0, exp: "Catálogo del Plan Municipal, Normativa General, art. 48: «Los planes especiales de protección podrán regular: a) El régimen de obras y usos autorizados en los edificios catalogados en cada caso particular. b) Las posibles ampliaciones en edificios catalogados». El grado de protección, la delimitación de las zonas arqueológicas y la relación de recintos no figuran en ese alcance. Además, según el art. 47, los planes especiales «sólo podrán modificar el régimen de autorización de obras cuando se justifique que es posible conseguir la protección y puesta en valor del edificio o elemento, con otro régimen distinto del recogido en este Catálogo»." },
  { id: "E54-44", tema: "E54", subtema: "Glosario de obras", tipo: "DEF",
    q: "Según el glosario de tipos de obras de la Normativa General del Catálogo del Plan Municipal de Pamplona (Texto Refundido aprobado por Acuerdo de la Comisión de Ordenación del Territorio de 18 de diciembre de 2002), la adecuación de un edificio a un uso existente o nuevo pudiendo variar elementos estructurales, espaciales, formales u ornamentales, pero manteniendo su traza y estructura general, se denomina:",
    o: ["Acondicionamiento.",
        "Reestructuración.",
        "Recuperación tipológica.",
        "Rehabilitación."],
    c: 3, exp: "Catálogo del Plan Municipal, Normativa General, art. 8 (glosario): «Rehabilitación: Adecuación de un edificio a un uso existente o nuevo pudiendo variar elementos estructurales, espaciales, formales u ornamentales pero manteniendo su traza y estructura general». El ACONDICIONAMIENTO es también una adecuación a un uso existente o nuevo, pero «sin variar sustancialmente su estructura o sus características formales u ornamentales»; la REESTRUCTURACIÓN es la «Alteración, total o parcial, del trazado o la organización espacial de un edificio o elemento», y la RECUPERACIÓN TIPOLÓGICA, la intervención «para restituir la traza o la organización espacial parcialmente perdidas»." },
  { id: "E54-45", tema: "E54", subtema: "Patrimonio natural: parques y jardines de grado 2", tipo: "ALCANCE",
    q: "Según la Normativa del patrimonio natural del Catálogo del Plan Municipal de Pamplona (Texto Refundido aprobado por Acuerdo de la Comisión de Ordenación del Territorio de 18 de diciembre de 2002), en los parques y jardines protegidos en grado 2, para mantener la densidad actual de árboles, las posibles talas deberán ir acompañadas por la plantación de un número similar de ejemplares:",
    o: ["También cuando la tala obedezca al mal estado de los ejemplares o al riesgo a corto plazo.",
        "Cuando la tala se justifique por la necesidad de ejecutar obras en el subsuelo.",
        "Salvo cuando la tala esté motivada por el mal estado de los ejemplares o el riesgo a corto plazo.",
        "Salvo cuando la tala cuente con un informe técnico favorable de los servicios municipales."],
    c: 2, exp: "Catálogo del Plan Municipal, Normativa del patrimonio natural, artículo 10.2 (parques y jardines de grado 2): «Para mantener la densidad actual de árboles en el ámbito de cada parque, las posibles talas deberán ir acompañadas por la plantación de un número similar de ejemplares. No se exigirá este requisito en el caso de talas motivadas por el mal estado de los ejemplares o el riesgo a corto plazo»: la c) es la correcta y la a) niega esa excepción. La b) reduce la reposición a las talas justificadas por obras en el subsuelo, que es el supuesto que en el artículo 10.3 permite autorizar la tala en las alineaciones arboladas; la d) toma el informe técnico favorable que el artículo 7 exige para autorizar excepcionalmente la eliminación de ejemplares, y que no está entre las excepciones a la reposición." },
  { id: "E54-46", tema: "E54", subtema: "Procedimiento: consulta previa", tipo: "SUP",
    q: "Un edificio catalogado en grado 3 conforme a la Normativa General del Catálogo del Plan Municipal de Pamplona (Texto Refundido aprobado por Acuerdo de la Comisión de Ordenación del Territorio de 18 de diciembre de 2002), cuya ficha solo señala como elemento de interés la fachada a la calle, solicita licencia para instalar placas solares en la cubierta sin intervenir en la fachada. Indique la respuesta CORRECTA:",
    o: ["No es preceptiva la consulta previa, porque las obras no afectan a los elementos de interés de la ficha.",
        "Es preceptiva la consulta previa, porque las obras incluyen instalaciones que afectan a la cubierta.",
        "Es preceptiva la consulta previa, porque se exige en todos los edificios catalogados, cualquiera que sea su grado.",
        "No es preceptiva la consulta previa, salvo que la exijan los servicios técnicos municipales al tramitar la licencia."],
    c: 1, exp: "Catálogo del Plan Municipal, Normativa General, art. 43.2: «En los edificios incluidos en el grado 3, esa consulta previa sólo será preceptiva si las obras previstas afectan a partes o elementos del edificio considerados de interés en la ficha correspondiente, o si incluyen instalaciones u obras que afecten a la cubierta». Las placas solares son una instalación que afecta a la cubierta, así que la consulta es preceptiva aunque no se toque la fachada: la b) es la correcta, y la a) olvida el segundo supuesto. La c) aplica al grado 3 la regla de los grados 1 y 2, en los que la consulta previa es preceptiva en todo caso (art. 43.1). La d) no tiene apoyo en el artículo: lo que pueden exigir los servicios técnicos municipales, tras una consulta previa aprobada, es la memoria de protección cuando haya cambiado alguna circunstancia del edificio (art. 43.5)." },
];
